<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/config/bootstrap.php';require dirname(__DIR__,2).'/app/admin.php';$admin=admin_require($pdo);$dir=dirname(__DIR__,2).'/uploads';$items=[];if(is_dir($dir)){foreach(array_diff(scandir($dir),['.','..','.htaccess']) as $f){$path=$dir.'/'.$f;if(is_file($path)&&preg_match('/\.(jpg|jpeg|png|gif|webp)$/i',$f))$items[]=$f;}}
admin_header('Media library',$admin);admin_show_flash(); ?><section class="content-card"><h2>Upload images</h2><p>JPEG, PNG, GIF, or WebP. Maximum file size: 5 MB.</p><form method="post" enctype="multipart/form-data" action="<?= e(admin_url('media/upload.php')) ?>"><?= admin_csrf_field() ?><div class="filter-form"><input type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" required><button class="button">Upload image</button></div></form></section><section class="media-grid"><?php foreach($items as $file): ?><article><img src="<?= e(site_url('uploads/'.rawurlencode($file))) ?>" alt=""><code><?= e($file) ?></code><button class="button secondary small" type="button" onclick="navigator.clipboard.writeText('<?= e(site_url('uploads/'.rawurlencode($file))) ?>')">Copy URL</button></article><?php endforeach ?><?php if(!$items): ?><p>No images uploaded yet.</p><?php endif ?></section><?php admin_footer(); ?>
